{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Saxagliptin, an adamantane-containing oral drug, has an absolute oral bioavailability of 50% (90% CI 48–53%) in healthy volunteers, directly supporting high F for the adamantane-amine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Mecamylamine, a small lipophilic bicyclic amine, was reported to have complete oral bioavailability in healthy subjects, supporting high F for the similarly lipophilic amine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Phenylpropanolamine, a small primary-amine drug, had an absolute oral bioavailability of 61.9% in healthy volunteers, supporting high F for the primary-amine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Lamotrigine has an absolute oral bioavailability of 98% in humans, demonstrating that small oral drugs can achieve high systemic exposure; supports high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an adamantane primary amine (rimantadine). Human absolute bioavailability data for the adamantane-containing saxagliptin (50%) and for small lipophilic/primary-amine drugs (mecamylamine complete, phenylpropanolamine 61.9%, lamotrigine 98%) consistently support high oral bioavailability. The only low-bioavailability record (cyclandelate) is formulation-specific and structurally distant, so it does not outweigh the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for rimantadine in the provided evidence set.",
    "Most evidence molecules have low Morgan similarity to the query; transferability is based on shared adamantane/amine features rather than high structural identity.",
    "The single low-bioavailability record (cyclandelate) is formulation-specific and structurally distant, limiting its relevance."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

